(81, 'Bloquer ma carte', '🔒 Votre carte a été bloquée temporairement. Un conseiller va traiter votre demande. En cas d\'urgence appelez le 0800 123 456.', '2026-06-05 22:40:05', NULL, 163, 'Imane Swiry', NULL, '4034144486691488', NULL, 'EN_ATTENTE'),
